import 'package:animated_text_kit/animated_text_kit.dart';
import 'package:flutter/material.dart';

class TypewriterExample extends StatelessWidget {
  const TypewriterExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 1. 기본 Typewriter 효과
            AnimatedTextKit(
              animatedTexts: [
                TypewriterAnimatedText(
                  '안녕하세요!',
                  textStyle: const TextStyle(
                    fontSize: 32,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                  speed: const Duration(milliseconds: 100),
                ),
              ],
              totalRepeatCount: 1,  // 한 번만 실행
            ),

            const SizedBox(height: 40),

            // 2. 여러 텍스트 순환
            DefaultTextStyle(
              style: const TextStyle(
                fontSize: 24,
                color: Colors.cyan,
                fontFamily: 'monospace',
              ),
              child: AnimatedTextKit(
                animatedTexts: [
                  TypewriterAnimatedText('Flutter가 좋아요'),
                  TypewriterAnimatedText('개발이 즐거워요'),
                  TypewriterAnimatedText('앱을 만들어요'),
                ],
                repeatForever: true,  // 무한 반복
                pause: const Duration(milliseconds: 1000),  // 텍스트 간 대기
              ),
            ),

            const SizedBox(height: 40),

            // 3. 타이핑 + 커서
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Text('> ', style: TextStyle(color: Colors.green, fontSize: 20)),
                AnimatedTextKit(
                  animatedTexts: [
                    TypewriterAnimatedText(
                      'npm install flutter',
                      textStyle: const TextStyle(
                        fontSize: 20,
                        color: Colors.green,
                        fontFamily: 'monospace',
                      ),
                      speed: const Duration(milliseconds: 50),
                      cursor: '|',  // 커서 문자
                    ),
                  ],
                  totalRepeatCount: 1,
                  displayFullTextOnTap: true,  // 탭하면 전체 텍스트 표시
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:animated_text_kit/animated_text_kit.dart';
import 'package:flutter/material.dart';

class VariousEffectsExample extends StatelessWidget {
  const VariousEffectsExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('다양한 효과')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 1. Fade 효과 (페이드 인/아웃)
            _buildSection(
              'Fade 효과',
              AnimatedTextKit(
                animatedTexts: [
                  FadeAnimatedText(
                    '페이드 인',
                    textStyle: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold),
                    duration: const Duration(milliseconds: 2000),
                  ),
                  FadeAnimatedText(
                    '페이드 아웃',
                    textStyle: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold),
                  ),
                ],
                repeatForever: true,
              ),
            ),

            // 2. Rotate 효과 (회전)
            _buildSection(
              'Rotate 효과',
              AnimatedTextKit(
                animatedTexts: [
                  RotateAnimatedText(
                    '회전!',
                    textStyle: const TextStyle(fontSize: 28, color: Colors.purple),
                    rotateOut: true,
                  ),
                  RotateAnimatedText(
                    'AWESOME',
                    textStyle: const TextStyle(fontSize: 28, color: Colors.blue),
                  ),
                  RotateAnimatedText(
                    'FLUTTER',
                    textStyle: const TextStyle(fontSize: 28, color: Colors.green),
                  ),
                ],
                repeatForever: true,
              ),
            ),

            // 3. Scale 효과 (확대/축소)
            _buildSection(
              'Scale 효과',
              AnimatedTextKit(
                animatedTexts: [
                  ScaleAnimatedText(
                    '확대!',
                    textStyle: const TextStyle(fontSize: 32, fontWeight: FontWeight.bold),
                    scalingFactor: 0.2,  // 시작 크기 비율
                  ),
                  ScaleAnimatedText(
                    '축소!',
                    textStyle: const TextStyle(fontSize: 32, fontWeight: FontWeight.bold),
                  ),
                ],
                repeatForever: true,
              ),
            ),

            // 4. Wavy 효과 (물결)
            _buildSection(
              'Wavy 효과',
              AnimatedTextKit(
                animatedTexts: [
                  WavyAnimatedText(
                    'Hello World',
                    textStyle: const TextStyle(
                      fontSize: 28,
                      fontWeight: FontWeight.bold,
                      color: Colors.teal,
                    ),
                    speed: const Duration(milliseconds: 200),
                  ),
                ],
                repeatForever: true,
                isRepeatingAnimation: true,
              ),
            ),

            // 5. Colorize 효과 (색상 변화)
            _buildSection(
              'Colorize 효과',
              AnimatedTextKit(
                animatedTexts: [
                  ColorizeAnimatedText(
                    'Colorize',
                    textStyle: const TextStyle(
                      fontSize: 36,
                      fontWeight: FontWeight.bold,
                    ),
                    colors: [
                      Colors.purple,
                      Colors.blue,
                      Colors.yellow,
                      Colors.red,
                    ],
                    speed: const Duration(milliseconds: 500),
                  ),
                ],
                repeatForever: true,
                isRepeatingAnimation: true,
              ),
            ),

            // 6. Flicker 효과 (깜빡임)
            _buildSection(
              'Flicker 효과',
              Container(
                color: Colors.black,
                padding: const EdgeInsets.all(16),
                child: AnimatedTextKit(
                  animatedTexts: [
                    FlickerAnimatedText(
                      'NEON',
                      textStyle: const TextStyle(
                        fontSize: 40,
                        color: Colors.pink,
                        fontWeight: FontWeight.bold,
                        shadows: [
                          Shadow(color: Colors.pink, blurRadius: 20),
                          Shadow(color: Colors.pink, blurRadius: 40),
                        ],
                      ),
                      speed: const Duration(milliseconds: 3000),
                    ),
                  ],
                  repeatForever: true,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSection(String title, Widget animation) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(title, style: const TextStyle(fontSize: 14, color: Colors.grey)),
        const SizedBox(height: 8),
        SizedBox(height: 80, child: Center(child: animation)),
        const Divider(),
        const SizedBox(height: 16),
      ],
    );
  }
}

import 'package:animated_text_kit/animated_text_kit.dart';
import 'package:flutter/material.dart';

class AnimatedSplashScreen extends StatefulWidget {
  const AnimatedSplashScreen({super.key});

  @override
  State<AnimatedSplashScreen> createState() => _AnimatedSplashScreenState();
}

class _AnimatedSplashScreenState extends State<AnimatedSplashScreen> {
  @override
  void initState() {
    super.initState();
    // 애니메이션 완료 후 메인 화면으로 이동
    Future.delayed(const Duration(seconds: 4), () {
      if (mounted) {
        Navigator.pushReplacementNamed(context, '/home');
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.indigo.shade900,
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 로고 애니메이션 (Scale)
            AnimatedTextKit(
              animatedTexts: [
                ScaleAnimatedText(
                  '🚀',
                  textStyle: const TextStyle(fontSize: 80),
                  scalingFactor: 0.5,
                  duration: const Duration(milliseconds: 1500),
                ),
              ],
              totalRepeatCount: 1,
            ),

            const SizedBox(height: 20),

            // 앱 이름 (Typewriter)
            AnimatedTextKit(
              animatedTexts: [
                TypewriterAnimatedText(
                  'My Awesome App',
                  textStyle: const TextStyle(
                    fontSize: 32,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                  speed: const Duration(milliseconds: 100),
                ),
              ],
              totalRepeatCount: 1,
            ),

            const SizedBox(height: 10),

            // 슬로건 (Fade)
            AnimatedTextKit(
              animatedTexts: [
                FadeAnimatedText(
                  '더 나은 내일을 위해',
                  textStyle: TextStyle(
                    fontSize: 16,
                    color: Colors.white.withOpacity(0.7),
                  ),
                  duration: const Duration(milliseconds: 2000),
                ),
              ],
              totalRepeatCount: 1,
            ),

            const SizedBox(height: 40),

            // 로딩 인디케이터
            const CircularProgressIndicator(
              valueColor: AlwaysStoppedAnimation<Color>(Colors.white),
            ),
          ],
        ),
      ),
    );
  }
}

// AI 챗봇 스타일 타이핑 효과
class ChatTypingEffect extends StatelessWidget {
  final String message;
  final VoidCallback onFinished;

  const ChatTypingEffect({
    super.key,
    required this.message,
    required this.onFinished,
  });

  @override
  Widget build(BuildContext context) {
    return AnimatedTextKit(
      animatedTexts: [
        TypewriterAnimatedText(
          message,
          textStyle: const TextStyle(
            fontSize: 16,
            color: Colors.black87,
          ),
          speed: const Duration(milliseconds: 30),
        ),
      ],
      totalRepeatCount: 1,
      onFinished: onFinished,
      displayFullTextOnTap: true,
    );
  }
}

// 동적 인사 메시지
class DynamicGreeting extends StatelessWidget {
  const DynamicGreeting({super.key});

  String _getGreeting() {
    final hour = DateTime.now().hour;
    if (hour < 12) return '좋은 아침이에요';
    if (hour < 18) return '좋은 오후예요';
    return '좋은 저녁이에요';
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedTextKit(
      animatedTexts: [
        TypewriterAnimatedText(
          _getGreeting(),
          textStyle: const TextStyle(
            fontSize: 28,
            fontWeight: FontWeight.bold,
          ),
          speed: const Duration(milliseconds: 80),
        ),
      ],
      totalRepeatCount: 1,
    );
  }
}

