import 'package:animated_text_kit/animated_text_kit.dart';
import 'package:flutter/material.dart';

class AdvancedControlExample extends StatefulWidget {
  const AdvancedControlExample({super.key});

  @override
  State<AdvancedControlExample> createState() => _AdvancedControlExampleState();
}

class _AdvancedControlExampleState extends State<AdvancedControlExample> {
  String _currentText = '';
  int _animationIndex = 0;
  bool _isFinished = false;
  Key _animationKey = UniqueKey();  // 재시작용 키

  final List<String> _texts = [
    '첫 번째 메시지입니다.',
    '두 번째 메시지입니다.',
    '세 번째 메시지입니다.',
    '마지막 메시지입니다!',
  ];

  void _restartAnimation() {
    setState(() {
      _animationKey = UniqueKey();
      _animationIndex = 0;
      _isFinished = false;
      _currentText = '';
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('고급 제어')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 상태 표시
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('현재 인덱스: $_animationIndex / ${_texts.length - 1}'),
                    Text('현재 텍스트: $_currentText'),
                    Text('완료 여부: ${_isFinished ? "완료" : "진행 중"}'),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 32),

            // 애니메이션 영역
            Container(
              height: 100,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: Colors.grey.shade100,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Center(
                child: AnimatedTextKit(
                  key: _animationKey,  // 키 변경으로 재시작
                  animatedTexts: _texts.map((text) {
                    return TypewriterAnimatedText(
                      text,
                      textStyle: const TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.bold,
                      ),
                      speed: const Duration(milliseconds: 50),
                    );
                  }).toList(),

                  // 각 텍스트 시작 시 콜백
                  onNext: (index, isLast) {
                    setState(() {
                      _animationIndex = index;
                      _currentText = _texts[index];
                    });
                  },

                  // 전체 애니메이션 완료 시 콜백
                  onFinished: () {
                    setState(() {
                      _isFinished = true;
                    });
                  },

                  // 각 텍스트 완료 시 콜백 (탭 포함)
                  onNextBeforePause: (index, isLast) {
                    debugPrint('텍스트 $index 표시 완료, 마지막: $isLast');
                  },

                  // 탭 시 전체 텍스트 표시
                  displayFullTextOnTap: true,

                  // 탭 콜백
                  onTap: () {
                    debugPrint('애니메이션 탭됨!');
                  },

                  // 한 번만 실행 (마지막 텍스트에서 멈춤)
                  totalRepeatCount: 1,

                  // 텍스트 간 대기 시간
                  pause: const Duration(milliseconds: 1000),

                  // 마지막 텍스트 표시 유지
                  stopPauseOnTap: true,
                ),
              ),
            ),

            const SizedBox(height: 32),

            // 컨트롤 버튼
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton.icon(
                  onPressed: _restartAnimation,
                  icon: const Icon(Icons.replay),
                  label: const Text('재시작'),
                ),
              ],
            ),

            const SizedBox(height: 32),
            const Divider(),
            const SizedBox(height: 16),

            // 조건부 애니메이션 예제
            const Text('조건부 애니메이션', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            _ConditionalAnimation(),
          ],
        ),
      ),
    );
  }
}

// 조건에 따라 다른 애니메이션 표시
class _ConditionalAnimation extends StatefulWidget {
  @override
  State<_ConditionalAnimation> createState() => _ConditionalAnimationState();
}

class _ConditionalAnimationState extends State<_ConditionalAnimation> {
  bool _isLoading = true;
  bool _hasError = false;

  void _toggleState() {
    setState(() {
      if (_isLoading) {
        _isLoading = false;
        _hasError = false;
      } else if (!_hasError) {
        _hasError = true;
      } else {
        _isLoading = true;
        _hasError = false;
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Container(
          height: 60,
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: _hasError ? Colors.red.shade50 : Colors.grey.shade100,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Center(
            child: _buildAnimation(),
          ),
        ),
        const SizedBox(height: 16),
        ElevatedButton(
          onPressed: _toggleState,
          child: const Text('상태 변경'),
        ),
      ],
    );
  }

  Widget _buildAnimation() {
    if (_isLoading) {
      return AnimatedTextKit(
        animatedTexts: [
          WavyAnimatedText(
            '로딩 중...',
            textStyle: const TextStyle(fontSize: 18),
          ),
        ],
        repeatForever: true,
      );
    }

    if (_hasError) {
      return AnimatedTextKit(
        animatedTexts: [
          FlickerAnimatedText(
            '오류 발생!',
            textStyle: const TextStyle(
              fontSize: 18,
              color: Colors.red,
              fontWeight: FontWeight.bold,
            ),
          ),
        ],
        repeatForever: true,
      );
    }

    return AnimatedTextKit(
      animatedTexts: [
        FadeAnimatedText(
          '성공!',
          textStyle: const TextStyle(
            fontSize: 18,
            color: Colors.green,
            fontWeight: FontWeight.bold,
          ),
        ),
      ],
      totalRepeatCount: 1,
    );
  }
}
